import{C as e,E as t,I as n,M as r,R as i,S as a,b as o,g as s,r as c,x as l,y as u}from"#entry";import{t as d}from"./CCrr1OGQ.js";import{t as f}from"./j-IC3ihx.js";import{t as p}from"./DSb9wSJa.js";import{t as m}from"./DKx5xoX8.js";var h={class:`shell content-section narrow-content legal-copy`},g={class:`breadcrumb`,"aria-label":`Migas de pan`},_={"aria-current":`page`},v={class:`page-header`},y={class:`article-meta`},b=e({__name:`mayorista-vs-minorista-diferencias`,setup(e){let b=f.find(e=>e.slug===`mayorista-vs-minorista-diferencias`);return m({title:b.title,description:b.excerpt,path:`/mayorista/blog/${b.slug}`}),p([{name:`Inicio`,path:`/mayorista`},{name:`Guías`,path:`/mayorista/blog`},{name:b.title,path:`/mayorista/blog/${b.slug}`}]),(e,f)=>{let p=c,m=d;return t(),u(`div`,h,[s(`nav`,g,[a(p,{to:`/mayorista`},{default:r(()=>[...f[0]||=[l(`Inicio`,-1)]]),_:1}),f[2]||=s(`span`,{"aria-hidden":`true`},`/`,-1),a(p,{to:`/mayorista/blog`},{default:r(()=>[...f[1]||=[l(`Guías`,-1)]]),_:1}),f[3]||=s(`span`,{"aria-hidden":`true`},`/`,-1),s(`span`,_,i(n(b).title),1)]),s(`header`,v,[s(`h1`,null,i(n(b).title),1)]),s(`p`,y,[s(`span`,null,i(n(b).readingMinutes)+` min de lectura`,1)]),f[5]||=o(`<p> &quot;Mayorista&quot; y &quot;minorista&quot; no son solo dos palabras distintas para comprar tecnología: son dos formas de comprar pensadas para objetivos distintos. Entender la diferencia te ayuda a saber qué esperar de cada una, y cuál te conviene según lo que estés armando. </p><h2>La compra minorista está pensada para uso propio</h2><p> Cuando comprás en una tienda minorista (una casa de electrónica, una tienda oficial de la marca), el precio incluye todos los costos de tener ese local abierto al público, con stock exhibido y atención personalizada para una sola unidad. Es la forma correcta de comprar si necesitás un equipo para vos. </p><h2>La compra mayorista está pensada para revender</h2><p> Comprar mayorista significa comprar en cantidad (no necesariamente cientos de unidades; en tecnología, un pedido mayorista puede empezar con pocas unidades) a un proveedor que trabaja con comercios y revendedores, no con el público final. El precio suele ser mejor porque no incluye la estructura de un local minorista, pero a cambio no vas a encontrar el mismo nivel de &quot;vidriera&quot;: no hay precios publicados fijos, el stock se confirma por consulta, y las condiciones (pago, entrega, garantía) se acuerdan en cada pedido. </p><h2>La diferencia no es solo de precio, es de relación</h2><p> Un buen proveedor mayorista funciona más como un socio comercial de largo plazo que como una tienda: te conviene tener un canal de comunicación directo (WhatsApp, en la mayoría de los casos en Argentina), consultar antes de cada pedido y construir una relación donde ambas partes se conocen. </p><h2>¿Cuál te conviene?</h2><p> Si necesitás un equipo para uso personal, la compra minorista es más simple y directa. Si tu objetivo es revender —tenés un local, una cuenta de venta en redes o en Mercado Libre, o estás por empezar— comprar mayorista es lo que te va a dar margen para que el negocio sea rentable. </p><p> Nexo Imports trabaja principalmente con comercios y revendedores en toda Argentina. También realizamos ventas minoristas según disponibilidad, aunque ese no es nuestro foco comercial. </p>`,10),a(m,{label:`Consultar condiciones mayoristas`,message:`Hola Nexo Imports, leí la guía sobre mayorista vs. minorista y quiero consultar las condiciones para comprar como revendedor.`}),s(`p`,null,[a(p,{to:`/mayorista/tecnologia-para-revendedores`},{default:r(()=>[...f[4]||=[l(` Ver más sobre cómo trabajamos con revendedores ↗ `,-1)]]),_:1})])])}}});export{b as default};